spmi_debug_bus: qcom,spmi-debug@6b12000 {
        compatible = "qcom,spmi-pmic-arb-debug";
        reg = <0 0x06b12000 0 0x60>, <0 0x7820a8 0 0x4>;
        reg-names = "core", "fuse";
        clocks = <&aoss_qmp>;
        clock-names = "core_clk";
        qcom,fuse-disable-bit = <24>;
        #address-cells = <2>;
        #size-cells = <0>;
        status = "okay";
}
